import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import '../../visualPage/CadastroAlunos.css'; // Arquivo CSS para o layout

const CadastroAlunos = () => {
  const navigate = useNavigate();

  // Estado para controlar os dados do aluno
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [dataCadastro, setDataCadastro] = useState('');
  const [inativo, setInativo] = useState(false);
  const [cpfCNPJ, setCpfCNPJ] = useState('');
  const [editingAluno, setEditingAluno] = useState(null);  // Estado para armazenar o aluno que está sendo editado

  // Estados para controlar habilitação de botões
  const [canCreate, setCanCreate] = useState(true);
  const [canEdit, setCanEdit] = useState(false);
  const [canDelete, setCanDelete] = useState(false);
  const [canConsult, setCanConsult] = useState(true);

  // Função para buscar alunos cadastrados no backend
  const fetchAlunos = async () => {
    try {
      const response = await axios.get('http://localhost:5000/alunos');
      const alunos = response.data;  // Armazena os alunos no estado, caso necessário
      if (alunos.length > 0) {
        setCanEdit(true);
        setCanDelete(true);
      }
    } catch (err) {
      console.error('Erro ao consultar alunos:', err);
    }
  };

  // Função para criar novo aluno
  const handleCreateNewAluno = async () => {
    try {
      await axios.post('http://localhost:5000/alunos', {
        nome,
        email,
        dataCadastro,
        inativo,
        cpfCNPJ
      });
      clearFields();  // Limpa os campos
    } catch (err) {
      console.error('Erro ao criar aluno:', err);
    }
  };

  // Função para salvar a edição
  const handleSaveEdit = async () => {
    try {
      await axios.put(`http://localhost:5000/alunos/${editingAluno.idAluno}`, {
        nome,
        email,
        dataCadastro,
        inativo,
        cpfCNPJ
      });
      clearFields();  // Limpa os campos
      setEditingAluno(null);  // Finaliza a edição
      setCanCreate(true);  // Habilita o botão de criar novamente
      setCanEdit(false);
      setCanDelete(false);
    } catch (err) {
      console.error('Erro ao salvar edição:', err);
    }
  };

  // Função para excluir aluno
  const handleDeleteAluno = async () => {
    if (!editingAluno) return;
    
    try {
      await axios.delete(`http://localhost:5000/alunos/${editingAluno.idAluno}`);
      clearFields();  // Limpa os campos após a exclusão
    } catch (err) {
      console.error('Erro ao excluir aluno:', err);
    }
  };

  // Função para consultar alunos
  const handleConsultAlunos = () => {
    navigate('/consultas/ConsultaAlunos');  // Redireciona para a página de consulta de alunos
  };

  // Função para limpar os campos do formulário
  const clearFields = () => {
    setNome('');
    setEmail('');
    setDataCadastro('');
    setCpfCNPJ('');
    setInativo(false);
    setEditingAluno(null);  // Reseta o aluno que está sendo editado
    setCanEdit(false);
    setCanDelete(false);
  };

  return (
    <div className="container-cadastro-alunos">
      <h2>{editingAluno ? 'Editar Aluno' : 'Cadastro de Alunos'}</h2>

      {/* Formulário de cadastro ou edição */}
      <div className="form-cadastro">
        <div>
          <input
            type="text"
            placeholder="Nome do Aluno"
            value={nome}
            onChange={(e) => setNome(e.target.value)}
          />
        </div>
        <div>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
        </div>
        <div>
          <input
            type="date"
            placeholder="Data de Cadastro"
            value={dataCadastro}
            onChange={(e) => setDataCadastro(e.target.value)}
          />
        </div>
        <div>
          <input
            type="text"
            placeholder="CPF ou CNPJ"
            value={cpfCNPJ}  // Novo campo cpfCNPJ
            onChange={(e) => setCpfCNPJ(e.target.value)}
          />
        </div>
        <div>
          <label>
            Inativo:
            <input
              type="checkbox"
              checked={inativo}
              onChange={(e) => setInativo(e.target.checked)}
            />
          </label>
        </div>

        {/* Botões */}
        <div className="buttons">
          <button onClick={handleCreateNewAluno} disabled={!canCreate}>Novo</button>
          <button onClick={handleSaveEdit} disabled={!canEdit}>Salvar</button>
          <button onClick={handleDeleteAluno} disabled={!canDelete}>Excluir</button>
          <button onClick={handleConsultAlunos} disabled={!canConsult}>Consultar</button>
        </div>
      </div>
    </div>
  );
};

export default CadastroAlunos;
